package vn.svframe.lively.world;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLong;public final class SemanticStructureRegistry{public enum OperationalState{OPEN,CLOSED,DAMAGED,RESTRICTED,UNDER_INVESTIGATION,ABANDONED,FESTIVAL,CONTROLLED}public record Bounds(String world,int minX,int minY,int minZ,int maxX,int maxY,int maxZ){public Bounds{Objects.requireNonNull(world);if(minX>maxX||minY>maxY||minZ>maxZ)throw new IllegalArgumentException("invalid bounds");}public boolean contains(String w,double x,double y,double z){return world.equals(w)&&x>=minX&&x<=maxX&&y>=minY&&y<=maxY&&z>=minZ&&z<=maxZ;}}public record Structure(String id,String type,Bounds bounds,Set<String>capabilities,Map<String,String>points,String parentId,String townId,OperationalState state,long revision){public Structure{Objects.requireNonNull(id);Objects.requireNonNull(type);Objects.requireNonNull(bounds);Objects.requireNonNull(state);if(id.isBlank()||id.length()>128)throw new IllegalArgumentException("invalid structure id");capabilities=Set.copyOf(capabilities);points=Map.copyOf(points);}public Structure withState(OperationalState s,long r){return new Structure(id,type,bounds,capabilities,points,parentId,townId,s,r);}public Structure withPoints(Map<String,String>p,long r){return new Structure(id,type,bounds,capabilities,p,parentId,townId,state,r);}public Structure withMembership(String p,String t,long r){return new Structure(id,type,bounds,capabilities,points,p,t,state,r);}}private final ConcurrentHashMap<String,Structure>structures=new ConcurrentHashMap<>();private final AtomicLong revision=new AtomicLong();public Structure register(Structure s){if(structures.size()>=100000&&!structures.containsKey(s.id()))throw new IllegalStateException("structure_limit");long r=revision.incrementAndGet();Structure n=new Structure(s.id(),s.type(),s.bounds(),s.capabilities(),s.points(),s.parentId(),s.townId(),s.state(),r);structures.put(n.id(),n);return n;}public boolean remove(String id){boolean removed=structures.remove(id)!=null;if(removed)revision.incrementAndGet();return removed;}public Optional<Structure>get(String id){return Optional.ofNullable(structures.get(id));}public Optional<Structure>setState(String id,OperationalState s){long r=revision.incrementAndGet();return Optional.ofNullable(structures.computeIfPresent(id,(k,c)->c.withState(s,r)));}public Optional<Structure>setPoint(String id,String name,double x,double y,double z){String key=normalize(name);long r=revision.incrementAndGet();return Optional.ofNullable(structures.computeIfPresent(id,(k,c)->{HashMap<String,String>p=new HashMap<>(c.points());p.put(key,x+","+y+","+z);return c.withPoints(p,r);}));}public Optional<Structure>removePoint(String id,String name){String key=normalize(name);long r=revision.incrementAndGet();return Optional.ofNullable(structures.computeIfPresent(id,(k,c)->{HashMap<String,String>p=new HashMap<>(c.points());p.remove(key);return c.withPoints(p,r);}));}public Optional<Structure>setMembership(String id,String parent,String town){if(parent!=null&&!structures.containsKey(parent))return Optional.empty();long r=revision.incrementAndGet();return Optional.ofNullable(structures.computeIfPresent(id,(k,c)->c.withMembership(parent,town,r)));}public List<Structure>at(String w,double x,double y,double z){return structures.values().stream().filter(s->s.bounds().contains(w,x,y,z)).sorted(Comparator.comparingLong(s->volume(s.bounds()))).toList();}public List<Structure>byType(String type){String n=normalize(type);return structures.values().stream().filter(s->normalize(s.type()).equals(n)).toList();}public Snapshot snapshot(){return new Snapshot(revision.get(),Map.copyOf(structures));}public void restore(Snapshot s){structures.clear();structures.putAll(s.structures());revision.set(Math.max(0L,s.revision()));}public record Snapshot(long revision,Map<String,Structure>structures){public Snapshot{structures=Map.copyOf(structures);}}private static long volume(Bounds b){return((long)b.maxX-b.minX+1)*((long)b.maxY-b.minY+1)*((long)b.maxZ-b.minZ+1);}private static String normalize(String v){return v==null?"":v.trim().toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9_.:-]","_");}}
